import numpy as np
from scipy.spatial.transform import Rotation as R
q=[0,-1.047,0,-2.64,0,1.536,-2.32]
a=[0,0,0,.0825,-.0825,0,.088];d=[.333,0,.316,0,.384,0,.107];alpha=[0,-np.pi/2,np.pi/2,np.pi/2,-np.pi/2,np.pi/2,np.pi/2]
def dh(a,d,alpha,q):
 c,s=np.cos(q),np.sin(q);ca,sa=np.cos(alpha),np.sin(alpha)
 return np.array([[c,-s*ca,s*sa,a*c],[s,c*ca,-c*sa,a*s],[0,sa,ca,d],[0,0,0,1]])
def mdh(a,d,alpha,q):
 c,s=np.cos(q),np.sin(q);ca,sa=np.cos(alpha),np.sin(alpha)
 return np.array([[c,-s,0,a],[s*ca,c*ca,-sa,-d*sa],[s*sa,c*sa,ca,d*ca],[0,0,0,1]])
for fun in (dh,mdh):
 T=np.eye(4)
 for v in zip(a,d,alpha,q):T=T@fun(*v)
 print(fun.__name__,np.round(T,3))
